const API_BASE = 'http://localhost:8080';

async function handleResponse(res) {
  // handle no content
  if (res.status === 204) return {};
  const len = res.headers.get("Content-Length");
  if (len === "0") return {};

  // read text first to gracefully handle empty responses
  const text = await res.text();
  if (!text) return {};

  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    data = {};
  }

  if (!res.ok) {
    const message = (data && (data.message || data.error)) || res.statusText || "Unknown error";
    throw new Error(message);
  }
  return data;
}

/* ----------------- PRODUCTS ------------------- */
export async function fetchProducts() {
  const res = await fetch(`${API_BASE}/api/products`);
  return handleResponse(res);
}

export async function fetchFiltered(category, sort) {
  const params = new URLSearchParams();
  if (category) params.append('category', category);
  if (sort) params.append('sort', sort);
  const res = await fetch(`${API_BASE}/api/products/filter?${params.toString()}`);
  return handleResponse(res);
}

/* ----------------- AUTH ----------------------- */
export async function register(email, password) {
  const res = await fetch(`${API_BASE}/api/auth/register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  return handleResponse(res);
}

export async function loginApi(email, password) {
  const res = await fetch(`${API_BASE}/api/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  return handleResponse(res);
}

/* ----------------- ORDERS --------------------- */
export async function placeOrder(cart) {
  const token = localStorage.getItem('token');

  // convert cart structure to backend shape: { items: [{ productId, quantity }] }
  const items = cart.map(item => ({
    productId: item.id,
    quantity: item.qty
  }));

  const res = await fetch(`${API_BASE}/api/orders`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: 'Bearer ' + token } : {})
    },
    body: JSON.stringify({ items })
  });

  return handleResponse(res);
}
